#!/usr/bin/env python3
"""Generate FFI stubs for the modules the Zignal fork leaves out (pool migration, EIP-681).

For each upstream source file it keeps every #[repr(C)] type definition and every exported
`ZCASHLC_*` constant verbatim (so cbindgen still emits the same C declarations and the Swift side
keeps compiling), and replaces every `extern "C" fn` body with one that records an "unsupported
in this build" error and returns the failure value for its return type. `zcashlc_free_*`
functions become no-ops, because the stubs never hand out anything to free.

The stub must be saved under the upstream file name (rust/src/migration.rs, rust/src/eip681.rs):
cbindgen, which writes the C header, finds modules by name and ignores #[path] and #[cfg].

Usage, with ECC's SDK checked out at tag 3.0.0:
  gen_stubs.py <ecc>/rust/src/migration.rs "Pool migration" > rust/src/migration.rs
  gen_stubs.py <ecc>/rust/src/eip681.rs "EIP-681 parsing" > rust/src/eip681.rs
Prints a summary of what it generated to stderr.
"""
import os
import re
import sys


def match_brace(text, i):
    """Index just past the brace block starting at text[i] == '{' (ignores braces in strings/comments)."""
    depth, j, n = 0, i, len(text)
    while j < n:
        c = text[j]
        if text.startswith("//", j):
            j = text.find("\n", j)
            j = n if j < 0 else j
            continue
        if text.startswith("/*", j):
            j = text.find("*/", j) + 2
            continue
        if c == '"':
            j += 1
            while j < n and text[j] != '"':
                j += 2 if text[j] == "\\" else 1
        elif c == "'" and re.match(r"'(\\.|[^\\'])'", text[j:j + 4]):
            j = text.find("'", j + 1)
        elif c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                return j + 1
        j += 1
    raise ValueError("unbalanced braces")


def leading_attrs(text, start):
    """Start index of the doc comments / attributes directly above `start`."""
    line_start = text.rfind("\n", 0, start) + 1
    while line_start > 0:
        prev_start = text.rfind("\n", 0, line_start - 1) + 1
        s = text[prev_start:line_start].strip()
        if s.startswith("///") or s.startswith("#["):
            line_start = prev_start
        else:
            break
    return line_start


def failure_value(ret):
    r = ret.strip()
    if not r:
        return None
    if r.startswith("*mut"):
        return "std::ptr::null_mut()"
    if r.startswith("*const"):
        return "std::ptr::null()"
    if r == "bool":
        return "false"
    if r in ("i8", "i16", "i32", "i64", "isize"):
        return "-1"
    if r in ("u8", "u16", "u32", "u64", "usize"):
        return "0"
    return "UNKNOWN"


def main(path, label):
    text = open(path).read()
    out = [
        f"//! Stubs for the `{label}` FFI, which the Zignal fork leaves out.",
        f"//! Generated by Scripts/gen_stubs.py from ECC SDK 3.0.0's rust/src/{os.path.basename(path)}.",
        "//! Do not edit by hand. The #[repr(C)] types and ZCASHLC_* constants are kept verbatim, so",
        "//! the C header and the Swift side are unchanged.",
        "#![allow(unused_variables, dead_code, clippy::missing_safety_doc)]",
        "",
        "@@IMPORTS@@",
        "",
        f'const UNSUPPORTED: &str = "{label} is not supported in this build of Zignal\'s SDK";',
        "",
        "fn unsupported() {",
        "    ffi_helpers::error_handling::update_last_error(anyhow::anyhow!(UNSUPPORTED));",
        "}",
        "",
    ]
    types, fns, consts, unknown, unresolved = 0, 0, 0, [], []

    # Exported constants (cbindgen turns them into #defines the Swift side switches on).
    for m in re.finditer(r"^pub const (ZCASHLC_\w+)\s*:[^;]*;[^\n]*", text, re.M):
        start = leading_attrs(text, m.start())
        out.append(text[start:m.end()].strip("\n"))
        consts += 1
    if consts:
        out.append("")

    for m in re.finditer(r"^[ \t]*#\[repr\(C\)\]", text, re.M):
        start = leading_attrs(text, m.start())
        # Item header after the attribute(s): struct/enum/union NAME ... {  or tuple/unit struct ;
        hdr = re.compile(r"(pub(\([^)]*\))?\s+)?(struct|enum|union)\s+\w+[^;{]*[;{]").search(text, m.end())
        if text[hdr.end() - 1] == "{":
            end = match_brace(text, hdr.end() - 1)
        else:
            end = hdr.end()
        out.append(text[start:end].strip("\n"))
        out.append("")
        types += 1

    for m in re.finditer(r'^[ \t]*pub\s+(unsafe\s+)?extern\s+"C"\s+fn\s+(\w+)', text, re.M):
        name = m.group(2)
        start = leading_attrs(text, m.start())
        # Signature: from `pub` to the body's opening brace at paren depth 0.
        j, depth = m.end(), 0
        while True:
            c = text[j]
            if c == "(":
                depth += 1
            elif c == ")":
                depth -= 1
            elif c == "{" and depth == 0:
                break
            j += 1
        sig = text[m.start():j].rstrip()
        ret = sig.split("->", 1)[1] if re.search(r"\)\s*->", sig) else ""
        attrs = text[start:m.start()].rstrip()
        attrs = "\n".join(l for l in attrs.split("\n") if l.strip().startswith("#["))
        if name.startswith("zcashlc_free_"):
            body = "{}"
        else:
            fv = failure_value(ret)
            if fv == "UNKNOWN":
                unknown.append((name, ret.strip()))
                body = "{\n    unsupported();\n    todo!(\"choose a failure value for this return type\")\n}"
            elif fv is None:
                body = "{\n    unsupported();\n}"
            else:
                body = "{\n    unsupported();\n    " + fv + "\n}"
        out.append((attrs + "\n" if attrs else "") + sig + " " + body)
        out.append("")
        fns += 1

    # Resolve the type names the kept code mentions.
    body_text = "\n".join(out)
    defined = set(re.findall(r"\b(?:struct|enum|union)\s+(\w+)", body_text))
    builtin = {"Self", "Option", "Box", "Vec", "String", "Result"}
    code_only = re.sub(r"//[^\n]*", "", body_text)
    code_only = re.sub(r'"(\\.|[^"\\])*"', '""', code_only)
    used = set(re.findall(r"\b([A-Z][A-Za-z0-9_]*)\b", code_only)) - defined - builtin
    used -= {"UNSUPPORTED", "C", "IMPORTS"}
    used = {u for u in used if not u.startswith("ZCASHLC_")}
    header = []
    for name in sorted(used):
        if re.search(rf"\b(struct|enum|type)\s+{name}\b", text):
            header.append(f"/// Opaque here: the real type lives in the upstream module.\npub struct {name} {{\n    _private: [u8; 0],\n}}\n")
            continue
        imp = re.search(rf"use\s+(crate::[\w:]*?)(?:::\{{[^}}]*\b{name}\b[^}}]*\}}|::{name})\s*;", text, re.S)
        if imp:
            header.append(f"use {imp.group(1)}::{name};")
            continue
        if name in ("CStr", "CString", "NonNull"):
            continue
        unresolved.append(name)
    still_unknown = []
    for fname, ret in unknown:
        variant = re.search(rf"enum\s+{re.escape(ret)}\s*\{{\s*(?:///[^\n]*\n\s*)*(\w+)", text)
        if variant:
            # A repr(C) enum: answer its first variant. The stubbed constructors never hand out
            # a value, so this is never read for real data.
            body_text = body_text.replace(
                'todo!("choose a failure value for this return type")', f"{ret}::{variant.group(1)}", 1)
        else:
            still_unknown.append((fname, ret))
    unknown[:] = still_unknown
    # Import only the C types the kept code mentions (an unused import is a compiler warning).
    code_now = re.sub(r"//[^\n]*", "", body_text)
    c_types = [t for t in ("c_char", "c_void") if re.search(rf"\b{t}\b", code_now)]
    imports = ("use std::ffi::" + (c_types[0] if len(c_types) == 1 else "{" + ", ".join(c_types) + "}") + ";") if c_types else ""
    body_text = body_text.replace("@@IMPORTS@@", imports, 1)
    head, rest = body_text.split("fn unsupported()", 1)
    sys.stdout.write(head + "\n".join(header) + "\n\nfn unsupported()" + rest)
    print(f"{path}: {types} repr(C) types kept, {consts} constants kept, {fns} functions stubbed", file=sys.stderr)
    for name in unresolved:
        print(f"  unresolved type: {name}", file=sys.stderr)
    for name, ret in unknown:
        print(f"  needs a hand-picked failure value: {name} -> {ret}", file=sys.stderr)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
